import { FC, memo } from 'react';

type Props = {
  panelNum: number;
  action: () => void;
};

export const BasePanel: FC<Props> = memo((props) => {
  const { panelNum, action } = props;
  return (
    <>
      <div>
        <button
          onClick={() => {
            action;
          }}
          className="panel gray"
        >
          {panelNum}
        </button>
      </div>
    </>
  );
});
